# Logos Oliv_Maintenance embarqués (base64) : icône multi-tailles 16-64 px (barre de titre, barre des tâches) et logo complet (Paramètres)
$LogoIcoB64  = ''
$LogoMarkB64 = ''
$LogoFullB64 = ''
function Get-EmbeddedImage([string]$B64, [switch]$Icon) {
    try {
        $ms = [IO.MemoryStream]::new([Convert]::FromBase64String($B64))
        if ($Icon) { $img = [Windows.Media.Imaging.BitmapFrame]::Create($ms, 'None', 'OnLoad') }
        else {
            $img = [Windows.Media.Imaging.BitmapImage]::new()
            $img.BeginInit()
            $img.CacheOption = 'OnLoad'
            $img.StreamSource = $ms
            $img.EndInit()
        }
        $img.Freeze(); $img
    } catch { $null }
}
$AppIcon = Get-EmbeddedImage $LogoIcoB64 -Icon
$Window = [Windows.Markup.XamlReader]::Load([System.Xml.XmlNodeReader]::new($Xaml))
if ($AppIcon) { $Window.Icon = $AppIcon }
$hl = $Window.FindName('HeadLogo'); $hm = Get-EmbeddedImage $LogoMarkB64
if ($hl -and $hm) { $hl.Source = $hm; $hl.Visibility = 'Visible' }
$Ui = @{}
foreach ($node in $Xaml.SelectNodes("//*[@*[local-name()='Name' and namespace-uri()='http://schemas.microsoft.com/winfx/2006/xaml']]")) {
    $n = $node.GetAttribute('Name', 'http://schemas.microsoft.com/winfx/2006/xaml')
    $Ui[$n] = $Window.FindName($n)
}

$Sync = [hashtable]::Synchronized(@{})
$Sync.Queue    = [System.Collections.Concurrent.ConcurrentQueue[string]]::new()
$Sync.Version  = $AppVersion
$Sync.Labels   = @{}
$Sync.Running  = $false
$Sync.Done     = $false
$Sync.Cancel   = $false
$Sync.Status   = 'Prêt'
$Sync.Params   = @{}
foreach ($k in $TaskLabels.Keys) { $Sync.Labels[$k] = $TaskLabels[$k] }

